import itertools

def clause(vals):
    # exactly one true among three
    return sum(vals)==1

def satisfies(x,y,z):
    # try to find a,b,c satisfying constraints
    for a,b,c in itertools.product([0,1], repeat=3):
        if clause((x,a,b)) and clause((y,b,c)) and clause((z,c,a)) and clause((a,b,c)):
            return True
    return False

for combo in itertools.product([0,1], repeat=3):
    x,y,z = combo
    sat = satisfies(x,y,z)
    print(combo, sat)
